-- Generated from constructor signatures. Do not edit; see source_imports.shared.contracts.
CREATE FUNCTION atlas.nonblank(value text) RETURNS boolean
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $nonblank$
 SELECT value COLLATE "C" ~  E'[^\\u0009-\\u000d\\u0020\\u0085\\u00a0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000]';
$nonblank$;

CREATE FUNCTION atlas.valid_construction_record(method text, arguments jsonb)
RETURNS boolean LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $contract$
SELECT CASE method
WHEN 'geodesic_trace' THEN public.jsonb_matches_schema( E'{"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false,"properties":{"source_ids":{"items":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},"title":"Source Ids","type":"array"},"feature_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Feature Id","type":"string"},"points":{"items":{"maxItems":2,"minItems":2,"prefixItems":[{"type":"number"},{"type":"number"}],"type":"array"},"title":"Points","type":"array"},"max_step_metres":{"title":"Max Step Metres","type":"number"}},"required":["source_ids","feature_id","points","max_step_metres"],"title":"geodesic_trace","type":"object"}'::json, arguments)
WHEN 'interpreted_geometry' THEN public.jsonb_matches_schema( E'{"$schema":"https://json-schema.org/draft/2020-12/schema","$defs":{"Point":{"additionalProperties":false,"properties":{"type":{"const":"Point","title":"Type","type":"string"},"coordinates":{"maxItems":2,"minItems":2,"prefixItems":[{"type":"number"},{"type":"number"}],"title":"Coordinates","type":"array"}},"required":["type","coordinates"],"title":"Point","type":"object"},"Polygon":{"additionalProperties":false,"properties":{"type":{"const":"Polygon","title":"Type","type":"string"},"coordinates":{"items":{"items":{"maxItems":2,"minItems":2,"prefixItems":[{"type":"number"},{"type":"number"}],"type":"array"},"type":"array"},"title":"Coordinates","type":"array"}},"required":["type","coordinates"],"title":"Polygon","type":"object"},"Selection":{"additionalProperties":false,"properties":{"feature_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Feature Id","type":"string"},"geometry":{"anyOf":[{"$ref":"#/$defs/Point"},{"$ref":"#/$defs/Polygon"}],"title":"Geometry"}},"required":["feature_id","geometry"],"title":"Selection","type":"object"}},"additionalProperties":false,"properties":{"source_ids":{"items":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},"title":"Source Ids","type":"array"},"selections":{"items":{"$ref":"#/$defs/Selection"},"title":"Selections","type":"array"}},"required":["source_ids","selections"],"title":"interpreted_geometry","type":"object"}'::json, arguments)
WHEN 'osm_way_chain' THEN public.jsonb_matches_schema( E'{"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false,"properties":{"way_source_ids":{"items":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},"title":"Way Source Ids","type":"array"},"feature_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Feature Id","type":"string"},"evidence_source_ids":{"anyOf":[{"items":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},"type":"array"},{"type":"null"}],"title":"Evidence Source Ids"}},"required":["way_source_ids","feature_id"],"title":"osm_way_chain","type":"object"}'::json, arguments)
WHEN 's130_areas' THEN public.jsonb_matches_schema( E'{"$schema":"https://json-schema.org/draft/2020-12/schema","$defs":{"FeatureIdentity":{"additionalProperties":false,"properties":{"feature_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Feature Id","type":"string"},"source_feature_id":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"integer"}],"title":"Source Feature Id"}},"required":["feature_id","source_feature_id"],"title":"FeatureIdentity","type":"object"}},"additionalProperties":false,"properties":{"source_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Source Id","type":"string"},"gml_member":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Gml Member","type":"string"},"selections":{"items":{"$ref":"#/$defs/FeatureIdentity"},"title":"Selections","type":"array"}},"required":["source_id","gml_member","selections"],"title":"s130_areas","type":"object"}'::json, arguments)
WHEN 'selected_osm_features' THEN public.jsonb_matches_schema( E'{"$schema":"https://json-schema.org/draft/2020-12/schema","$defs":{"OsmSelection":{"additionalProperties":false,"properties":{"feature_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Feature Id","type":"string"},"source_feature_id":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"integer"}],"title":"Source Feature Id"},"object_type":{"enum":["node","way","relation"],"title":"Object Type","type":"string"},"expected_tags":{"additionalProperties":{"type":"string"},"title":"Expected Tags","type":"object"}},"required":["feature_id","source_feature_id","object_type"],"title":"OsmSelection","type":"object"}},"additionalProperties":false,"properties":{"source_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Source Id","type":"string"},"selections":{"items":{"$ref":"#/$defs/OsmSelection"},"title":"Selections","type":"array"}},"required":["source_id","selections"],"title":"selected_osm_features","type":"object"}'::json, arguments)
WHEN 'selected_vector_features' THEN public.jsonb_matches_schema( E'{"$schema":"https://json-schema.org/draft/2020-12/schema","$defs":{"VectorSelection":{"additionalProperties":false,"properties":{"feature_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Feature Id","type":"string"},"source_feature_id":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"integer"}],"title":"Source Feature Id"},"polygon_containing":{"maxItems":2,"minItems":2,"prefixItems":[{"type":"number"},{"type":"number"}],"title":"Polygon Containing","type":"array"},"fill_holes":{"title":"Fill Holes","type":"boolean"}},"required":["feature_id","source_feature_id"],"title":"VectorSelection","type":"object"}},"additionalProperties":false,"properties":{"source_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Source Id","type":"string"},"id_field":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Id Field","type":"string"},"selections":{"items":{"$ref":"#/$defs/VectorSelection"},"title":"Selections","type":"array"},"member":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"null"}],"title":"Member"},"layer":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"null"}],"title":"Layer"}},"required":["source_id","id_field","selections"],"title":"selected_vector_features","type":"object"}'::json, arguments)
WHEN 'watershed_boundary' THEN public.jsonb_matches_schema( E'{"$schema":"https://json-schema.org/draft/2020-12/schema","$defs":{"DrainageSettings":{"additionalProperties":false,"properties":{"basins":{"items":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"$ref":"#/$defs/FileSelection"}]},"title":"Basins","type":"array"},"basin_attribute":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Basin Attribute","type":"string"},"groups":{"additionalProperties":false,"patternProperties":{"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]":{"items":{},"type":"array"}},"title":"Groups","type":"object"},"waterways":{"items":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"$ref":"#/$defs/FileSelection"}]},"title":"Waterways","type":"array"},"reverse_waterways":{"items":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"integer"}]},"title":"Reverse Waterways","type":"array"},"waterway_groups":{"additionalProperties":false,"patternProperties":{"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]":{"items":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"integer"}]},"type":"array"}},"title":"Waterway Groups","type":"object"}},"required":["basins","basin_attribute","groups"],"title":"DrainageSettings","type":"object"},"FileSelection":{"additionalProperties":false,"properties":{"source":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Source","type":"string"},"member":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Member","type":"string"}},"required":["source"],"title":"FileSelection","type":"object"},"GeoJSONLine":{"additionalProperties":false,"properties":{"source":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Source","type":"string"},"member":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Member","type":"string"},"geojson_feature":{"title":"Geojson Feature","type":"integer"}},"required":["source","geojson_feature"],"title":"GeoJSONLine","type":"object"},"MultipartSource":{"additionalProperties":false,"properties":{"parts":{"items":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},"title":"Parts","type":"array"},"sha256":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Sha256","type":"string"},"size_bytes":{"title":"Size Bytes","type":"integer"},"filename":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Filename","type":"string"}},"required":["parts","sha256","size_bytes","filename"],"title":"MultipartSource","type":"object"},"OsmRiverLine":{"additionalProperties":false,"properties":{"source":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Source","type":"string"},"relation":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"integer"}],"title":"Relation"},"role":{"title":"Role","type":"string"}},"required":["source","relation","role"],"title":"OsmRiverLine","type":"object"},"OsmWayLine":{"additionalProperties":false,"properties":{"source":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Source","type":"string"},"way":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"integer"}],"title":"Way"}},"required":["source","way"],"title":"OsmWayLine","type":"object"},"TerrainDomain":{"additionalProperties":false,"properties":{"bounds":{"maxItems":4,"minItems":4,"prefixItems":[{"type":"number"},{"type":"number"},{"type":"number"},{"type":"number"}],"title":"Bounds","type":"array"},"crs":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"integer"}],"title":"Crs"},"output_bounds":{"anyOf":[{"maxItems":4,"minItems":4,"prefixItems":[{"type":"number"},{"type":"number"},{"type":"number"},{"type":"number"}],"type":"array"},{"type":"null"}],"title":"Output Bounds"}},"required":["bounds"],"title":"TerrainDomain","type":"object"},"TerrainSettings":{"additionalProperties":false,"properties":{"domains":{"items":{"$ref":"#/$defs/TerrainDomain"},"title":"Domains","type":"array"},"primary":{"items":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"$ref":"#/$defs/FileSelection"}]},"title":"Primary","type":"array"},"drainage":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Drainage","type":"string"},"interfaces":{"items":{"maxItems":2,"minItems":2,"prefixItems":[{"anyOf":[{"type":"integer"},{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"}]},{"anyOf":[{"type":"integer"},{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"}]}],"type":"array"},"title":"Interfaces","type":"array"},"secondary":{"items":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"$ref":"#/$defs/FileSelection"}]},"title":"Secondary","type":"array"},"height_offset":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Height Offset","type":"string"},"closed_sinks":{"items":{"additionalProperties":true,"type":"object"},"title":"Closed Sinks","type":"array"},"ocean_mask":{"additionalProperties":true,"title":"Ocean Mask","type":"object"}},"required":["domains","primary","drainage","interfaces"],"title":"TerrainSettings","type":"object"}},"additionalProperties":false,"properties":{"feature_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Feature Id","type":"string"},"sources":{"additionalProperties":false,"patternProperties":{"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"$ref":"#/$defs/MultipartSource"}]}},"title":"Sources","type":"object"},"lines":{"additionalProperties":false,"patternProperties":{"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]":{"anyOf":[{"$ref":"#/$defs/GeoJSONLine"},{"$ref":"#/$defs/OsmWayLine"},{"$ref":"#/$defs/OsmRiverLine"}]}},"title":"Lines","type":"object"},"sections":{"items":{"additionalProperties":true,"type":"object"},"title":"Sections","type":"array"},"joins":{"items":{"additionalProperties":true,"type":"object"},"title":"Joins","type":"array"},"start":{"additionalProperties":true,"title":"Start","type":"object"},"end":{"additionalProperties":true,"title":"End","type":"object"},"terrains":{"anyOf":[{"additionalProperties":false,"patternProperties":{"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]":{"$ref":"#/$defs/TerrainSettings"}},"type":"object"},{"type":"null"}],"title":"Terrains"},"drainage":{"anyOf":[{"additionalProperties":false,"patternProperties":{"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]":{"$ref":"#/$defs/DrainageSettings"}},"type":"object"},{"type":"null"}],"title":"Drainage"},"evidence_sources":{"anyOf":[{"items":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},"type":"array"},{"type":"null"}],"title":"Evidence Sources"}},"required":["feature_id","sources","lines","sections","joins","start","end"],"title":"watershed_boundary","type":"object"}'::json, arguments)
ELSE FALSE END;
$contract$;

CREATE FUNCTION atlas.construction_source_ids(method text, arguments jsonb)
RETURNS SETOF text LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $sources$
SELECT DISTINCT value #>> '{}' FROM unnest(CASE method
WHEN 'geodesic_trace' THEN ARRAY['lax $."source_ids"[*]']::jsonpath[]
WHEN 'interpreted_geometry' THEN ARRAY['lax $."source_ids"[*]']::jsonpath[]
WHEN 'osm_way_chain' THEN ARRAY['lax $."evidence_source_ids"[*]','lax $."way_source_ids"[*]']::jsonpath[]
WHEN 's130_areas' THEN ARRAY['lax $."source_id"']::jsonpath[]
WHEN 'selected_osm_features' THEN ARRAY['lax $."source_id"']::jsonpath[]
WHEN 'selected_vector_features' THEN ARRAY['lax $."source_id"']::jsonpath[]
WHEN 'watershed_boundary' THEN ARRAY['lax $."evidence_sources"[*]','lax $."sources".*','lax $."sources".*."parts"[*]']::jsonpath[]
ELSE ARRAY[]::jsonpath[] END) AS paths(path)
CROSS JOIN LATERAL jsonb_path_query(arguments,path,'{}'::jsonb,true) AS refs(value)
WHERE jsonb_typeof(value)='string';
$sources$;
